"""Rank policies (protocol 3.0).

Every policy is *causal*: the rank of a packet is computed on the enqueue
attempt itself, is immutable afterwards and is advanced even when the attempt
is rejected by the staging-FIFO byte limit.  All arithmetic is exact Python
integer arithmetic; the WFQ tags are the quantized finish times required by
the protocol (``ceil(length * 1048576 / weight)``), never floats.

State that a checkpoint must isolate is split in two places:

* scalar policy state (the FIFO service counter, the WFQ virtual time) lives
  in ``run.sc`` and is copied by ``save``,
* keyed state (WFQ weights and finish tags) lives in plain dicts and is
  protected by the run's undo log (``run.log_set``).
"""

# Slots of the per-run scalar vector maintained by the scheduler.
K_T, K_P, K_L, K_A, K_FT, K_V = range(6)
SCALAR_SLOTS = 6

SCALE = 1048576  # 2**20 quantization of the WFQ finish tags


class SchedulingAlgorithm:
    """Base class: rank on attempt, feedback on successful service."""

    kind = None

    def rank(self, run, flow, length, flow_size):
        raise NotImplementedError('subclasses must assign a rank')

    def post_service(self, run, rank):
        """Feedback for a *successful* pop only (drops/idle visits: never)."""

    def set_weight(self, run, flow, weight):
        """Reconfiguration hook; only WFQ has feedback weights."""

    def certificate(self, run):
        raise NotImplementedError('subclasses must certify their state')

    def reset(self):
        pass


class FifoAlgorithm(SchedulingAlgorithm):
    """First-in first-out: rank is the new value of a monotone counter."""

    kind = 'fifo'
    __slots__ = ()

    def rank(self, run, flow, length, flow_size):
        sc = run.sc
        value = sc[K_FT] + 1
        sc[K_FT] = value
        return value

    def certificate(self, run):
        return {'kind': 'fifo', 'time': run.sc[K_FT]}


class SpAlgorithm(SchedulingAlgorithm):
    """Strict priority from a declared, immutable flow/level table."""

    kind = 'sp'
    __slots__ = ('levels',)

    def __init__(self, levels):
        self.levels = levels

    def rank(self, run, flow, length, flow_size):
        return self.levels[flow]

    def certificate(self, run):
        levels = self.levels
        return {'kind': 'sp',
                'levels': [[flow, levels[flow]] for flow in sorted(levels)]}


class pFabricAlgorithm(SchedulingAlgorithm):
    """Shortest-first-flow: rank is the supplied (unclipped) flow size."""

    kind = 'sff'
    __slots__ = ()

    def rank(self, run, flow, length, flow_size):
        return flow_size

    def certificate(self, run):
        return {'kind': 'sff'}


SffAlgorithm = pFabricAlgorithm


class WFQAlgorithm(SchedulingAlgorithm):
    """Quantized weighted fair queueing with a max-clamped virtual time."""

    kind = 'wfq'
    __slots__ = ('weights', 'finish')

    def __init__(self, weights):
        self.weights = weights
        self.finish = dict.fromkeys(weights, 0)

    def rank(self, run, flow, length, flow_size):
        weights = self.weights
        weight = weights[flow]
        finish = self.finish
        tag = finish[flow]
        virtual = run.sc[K_V]
        if virtual > tag:
            tag = virtual
        tag += -(-(length * SCALE) // weight)
        run.log_set(finish, flow, tag)
        finish[flow] = tag
        return tag

    def post_service(self, run, rank):
        sc = run.sc
        if rank > sc[K_V]:
            run.log_set(sc, K_V, rank)
            sc[K_V] = rank

    def set_weight(self, run, flow, weight):
        weights = self.weights
        run.log_set(weights, flow, weight)
        weights[flow] = weight

    def certificate(self, run):
        weights = self.weights
        finish = self.finish
        return {'kind': 'wfq',
                'virtual_time': run.sc[K_V],
                'weights': [[flow, weights[flow]] for flow in sorted(weights)],
                'finish': [[flow, finish[flow]] for flow in sorted(finish)]}


# Accept either spelling of the flow-size policy.
WFQAlgorithm.weight_update = WFQAlgorithm.set_weight


def build_policy(spec):
    """Instantiate the declared policy from its request object."""
    kind = spec['kind']
    if kind == 'fifo':
        return FifoAlgorithm()
    if kind == 'sff' or kind == 'pfabric':
        return pFabricAlgorithm()
    if kind == 'sp':
        return SpAlgorithm({flow: level for flow, level in spec['levels']})
    if kind == 'wfq':
        return WFQAlgorithm({flow: weight for flow, weight in spec['weights']})
    raise ValueError('unknown policy kind: %r' % (kind,))
