"""Build protocol-boundary stress batches and time the CLI."""
import json, random, subprocess, sys, time, os

def partition(U, count, rng):
    inner = sorted(rng.sample(range(1, U), min(count, U - 1)))
    return [0] + inner + [U]

def case_backlog():
    rng = random.Random(7)
    U = 1 << 20
    R = 32
    ev = []
    for i in range(60000):
        ev.append(['enqueue', i, rng.randrange(3), rng.randint(1, 1500), rng.randrange(U)])
        if i % 3 == 0:
            ev.append(['dequeue', 1])
    spec = {'banks': 8, 'load_balancers': 4, 'fifo_bytes': 40 * 10 ** 6,
            'pifo_bytes': 40 * 10 ** 6, 'refill_batch': 32, 'sample_period': 100,
            'borders': partition(U, R, rng), 'policy': {'kind': 'sff'}, 'events': ev}
    return {'runs': [spec]}

def case_branch():
    rng = random.Random(11)
    U = 1 << 20
    ev = []
    nid = 0
    for round_ in range(400):
        ev.append(['save', round_ % 4])
        for _ in range(50):
            ev.append(['enqueue', nid, rng.randrange(3), rng.randint(1, 900), rng.randrange(U)])
            nid += 1
        for _ in range(3):
            ev.append(['dequeue', 2])
        ev.append(['restore', round_ % 4])
    spec = {'banks': 4, 'load_balancers': 2, 'fifo_bytes': 10 ** 9,
            'pifo_bytes': 10 ** 9, 'refill_batch': 8, 'sample_period': 100000,
            'borders': [0, 1000, U], 'policy': {'kind': 'wfq', 'weights': [[0, 5], [1, 7], [2, 1024]]},
            'events': ev}
    return {'runs': [spec]}

def case_samples():
    rng = random.Random(13)
    U = 1 << 20
    ev = []
    nid = 0
    for i in range(6000):
        ev.append(['enqueue', nid, 0, 5, rng.randrange(U)]); nid += 1
        if i % 2 == 0:
            ev.append(['sample'])
    spec = {'banks': 16, 'load_balancers': 8, 'fifo_bytes': 10 ** 9, 'pifo_bytes': 10 ** 9,
            'refill_batch': 16, 'sample_period': 60,
            'borders': partition(U, 64, rng), 'policy': {'kind': 'fifo'}, 'events': ev}
    return {'runs': [spec]}

def case_repartition():
    rng = random.Random(17)
    U = 1 << 24
    ev = []
    nid = 0
    for i in range(60):
        ev.append(['repartition', partition(U, 64, rng)])
        for _ in range(200):
            ev.append(['enqueue', nid, 0, 3, rng.randrange(U)]); nid += 1
        ev.append(['dequeue', 30])
    spec = {'banks': 16, 'load_balancers': 8, 'fifo_bytes': 10 ** 9, 'pifo_bytes': 10 ** 9,
            'refill_batch': 32, 'sample_period': 100000,
            'borders': partition(U, 64, rng), 'policy': {'kind': 'sff'}, 'events': ev}
    return {'runs': [spec]}

def case_pushout():
    rng = random.Random(19)
    U = 1 << 20
    ev = []
    nid = 0
    for i in range(20000):
        ev.append(['enqueue', nid, 0, rng.randint(1, 900), rng.randrange(U)]); nid += 1
        if i % 2 == 0:
            ev.append(['dequeue', 1])
        if i % 17 == 0:
            ev.append(['cancel', rng.randrange(nid)])
    spec = {'banks': 2, 'load_balancers': 1, 'fifo_bytes': 3000, 'pifo_bytes': 2500,
            'refill_batch': 32, 'sample_period': 500,
            'borders': partition(U, 8, rng), 'policy': {'kind': 'sff'}, 'events': ev}
    return {'runs': [spec]}

def case_bigout():
    rng = random.Random(23)
    ev = []
    for i in range(20000):
        ev.append(['dequeue', 5])
    spec = {'banks': 1, 'load_balancers': 1, 'fifo_bytes': 10, 'pifo_bytes': 10,
            'refill_batch': 1, 'sample_period': 100000, 'borders': [0, 5],
            'policy': {'kind': 'fifo'}, 'events': ev}
    return {'runs': [spec]}

def main():
    which = sys.argv[1] if len(sys.argv) > 1 else 'all'
    cases = {'backlog': case_backlog, 'branch': case_branch, 'samples': case_samples,
             'repartition': case_repartition, 'pushout': case_pushout, 'bigout': case_bigout}
    for name, factory in cases.items():
        if which not in ('all', name):
            continue
        request = factory()
        data = json.dumps(request).encode()
        nops = sum(len(r['events']) for r in request['runs'])
        open('/workspace/tmp/stress_%s.json' % name, 'wb').write(data)
        start = time.time()
        proc = subprocess.run([sys.executable, '-I', '-B', '/workspace/submission/cli.py'],
                              input=data, capture_output=True)
        used = resource_peak()
        print('%-11s input %8d bytes  ops %7d  rc %d  out %9d  cpu %6.2fs  peakRSS %s' %
              (name, len(data), nops, proc.returncode, len(proc.stdout), time.time() - start, used))
        if proc.returncode:
            print(proc.stderr.decode()[-3000:])

def resource_peak():
    return '-'

if __name__ == '__main__':
    main()
